        put("m3_meaning", "“Within a Yama — Rasodvega.” Eating again within a Yama is said to disturb Rasa (the nutritive essence / digestive process).", "“याम के भीतर — रसोद्वेग।” याम के भीतर फिर खाने से रस (पोषक सार / पाचन प्रक्रिया) में उद्वेग कहा गया है।", "“याममध्ये रसोद्वेगः।” याममध्ये पुनर्भोजनेन रसस्य उद्वेगः उक्तः।")
        put("m4_meaning", "“Beyond the pair — Balakshaya.” When two Yamas are exceeded, strength (Bala) is said to diminish.", "“युग्म के बाद — बलक्षय।” दो याम बीत जाने पर बल का क्षय कहा गया है।", "“युग्मातीते बलक्षयः।” यामद्वये अतीते बलस्य क्षयः उक्तः।")
        put("m1_app", "In AHARA: intervals shorter than {0} h are counted as “within a Yama”.", "आहार में: {0} घंटे से छोटे अंतराल “याम के भीतर” गिने जाते हैं।", "आहारे: {0} होराभ्यः न्यूनानि अन्तरालानि “याममध्ये” इति गण्यन्ते।")
        put("m2_app", "In AHARA: intervals longer than {1} h, and skipped meals, are counted as extended gaps.", "आहार में: {1} घंटे से लंबे अंतराल और छूटे भोजन दीर्घ अंतराल गिने जाते हैं।", "आहारे: {1} होराभ्यः अधिकानि अन्तरालानि त्यक्तभोजनानि च दीर्घान्तरालानि इति गण्यन्ते।")
        put("m3_app", "In AHARA: post-meal sensations after meals taken within {0} h are compared with those after other meals.", "आहार में: {0} घंटे के भीतर लिए भोजन के बाद की अनुभूतियों की तुलना अन्य भोजन से की जाती है।", "आहारे: {0} होराभ्यन्तरे भुक्तानन्तरानुभवाः अन्यभोजनानुभवैः सह तुल्यन्ते।")
        put("m4_app", "In AHARA: energy reported before meals that follow gaps longer than {1} h is compared with other meals.", "आहार में: {1} घंटे से लंबे अंतराल के बाद के भोजन से पहले की ऊर्जा की तुलना अन्य भोजन से की जाती है।", "आहारे: {1} होराधिकान्तरालानन्तरं भोजनात् पूर्वं बलम् अन्यैः सह तुल्यते।")
        put("shloka_hi", "एक याम (लगभग तीन घंटे) के भीतर पुनः भोजन नहीं करना चाहिए, और दो याम (लगभग छह घंटे) से अधिक बिना भोजन के नहीं रहना चाहिए। एक याम के भीतर भोजन करने से रस का उद्वेग (पाचन में विक्षोभ) होता है, और दो याम बीत जाने पर बल का क्षय होता है।", "एक याम (लगभग तीन घंटे) के भीतर पुनः भोजन नहीं करना चाहिए, और दो याम (लगभग छह घंटे) से अधिक बिना भोजन के नहीं रहना चाहिए। एक याम के भीतर भोजन करने से रस का उद्वेग (पाचन में विक्षोभ) होता है, और दो याम बीत जाने पर बल का क्षय होता है।", "एक याम (लगभग तीन घंटे) के भीतर पुनः भोजन नहीं करना चाहिए, और दो याम (लगभग छह घंटे) से अधिक बिना भोजन के नहीं रहना चाहिए। एक याम के भीतर भोजन करने से रस का उद्वेग (पाचन में विक्षोभ) होता है, और दो याम बीत जाने पर बल का क्षय होता है।")
        put("shloka_en", "One should not eat again within one Yama (about three hours), nor let two Yamas (about six hours) pass without food. Eating within a Yama causes Rasodvega — a disturbance of Rasa and digestion; when two Yamas are exceeded, Balakshaya — a loss of strength — follows.", "One should not eat again within one Yama (about three hours), nor let two Yamas (about six hours) pass without food. Eating within a Yama causes Rasodvega — a disturbance of Rasa and digestion; when two Yamas are exceeded, Balakshaya — a loss of strength — follows.", "One should not eat again within one Yama (about three hours), nor let two Yamas (about six hours) pass without food. Eating within a Yama causes Rasodvega — a disturbance of Rasa and digestion; when two Yamas are exceeded, Balakshaya — a loss of strength — follows.")
        put("padaccheda", "Word division (Padaccheda)", "पदच्छेद", "पदच्छेदः")
        put("hindi_interpretation", "Hindi interpretation", "हिंदी व्याख्या", "हिन्दीव्याख्या")
